package com.pawsshop.model; import javax.persistence.*; import java.math.BigDecimal;
@Entity public class SaleItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long productId; private String productName; private int quantity; @Column(precision=12,scale=2) private BigDecimal unitPrice; @Column(precision=12,scale=2) private BigDecimal subtotal;
 public Long getId(){return id;} public Long getProductId(){return productId;} public void setProductId(Long v){productId=v;} public String getProductName(){return productName;} public void setProductName(String v){productName=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} }
